<div class="wrap">
  <h1>Hitelkalkulátor</h1>
  <p class="sub">Add meg a hitelösszeget, az éves kamatot és a futamidőt — a havi törlesztőrészletet és a tőke–kamat bontást itt kapod meg.</p>

  <form id="form" class="card" novalidate>
    <div class="grid">
      <div class="field">
        <label for="amount">Hitelösszeg (Ft)</label>
        <input id="amount" name="amount" type="number" inputmode="decimal" min="1" step="any" placeholder="pl. 10 000 000" aria-describedby="err">
      </div>
      <div class="field">
        <label for="rate">Éves kamat (%)</label>
        <input id="rate" name="rate" type="number" inputmode="decimal" min="0" step="any" placeholder="pl. 8,5" aria-describedby="err">
      </div>
      <div class="field">
        <label for="months">Futamidő (hónap)</label>
        <input id="months" name="months" type="number" inputmode="numeric" min="1" step="1" placeholder="pl. 240" aria-describedby="err">
      </div>
    </div>
    <button class="btn" type="submit">Számolás</button>
    <p class="err" id="err" role="alert" aria-live="polite"></p>
  </form>

  <div id="live" aria-live="polite" class="sr-only" style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)"></div>

  <section id="summary" class="card" hidden>
    <h2>Eredmény</h2>
    <div class="stats">
      <div class="stat accent"><div class="k">Havi törlesztőrészlet</div><div class="v" id="s-payment">–</div></div>
      <div class="stat"><div class="k">Teljes visszafizetés</div><div class="v" id="s-total">–</div></div>
      <div class="stat"><div class="k">Összes kamat</div><div class="v" id="s-interest">–</div></div>
    </div>
    <div class="chart" aria-hidden="true">
