</div>

<script>
(function(){
  "use strict";
  var nf = new Intl.NumberFormat('hu-HU',{maximumFractionDigits:0});
  var pf = new Intl.NumberFormat('hu-HU',{maximumFractionDigits:1});
  var KEY='loan-calc-v1';

  var form=document.getElementById('form');
  var amountEl=document.getElementById('amount');
  var rateEl=document.getElementById('rate');
  var monthsEl=document.getElementById('months');
  var errEl=document.getElementById('err');
  var live=document.getElementById('live');
  var summary=document.getElementById('summary');
  var breakdown=document.getElementById('breakdown');
  var tbody=document.getElementById('tbody');

  function fmt(v){return nf.format(Math.round(v))+' Ft';}
  function pct(v){return pf.format(v)+'%';}

  function compute(amount,ratePct,months){
    var r=ratePct/100/12, payment, balance=amount;
    var totalInterest=0, totalPrincipal=0, years=[], curYear=1;
    var y={year:1,principal:0,interest:0,payment:0};
    for(var m=1;m<=months;m++){
      var interest=balance*r;
      var principal=payment-interest;
      balance=balance-principal;
      if(balance<0)balance=0;
      y.principal+=principal; y.interest+=interest; y.payment+=payment;
      if(m%12===0){ years.push(y); curYear++; y={year:curYear,principal:0,interest:0,payment:0}; }
    }
    if(months%12!==0) years.push(y);
    for(var i=0;i<years.length;i++){totalPrincipal+=years[i].principal;totalInterest+=years[i].interest;}
    return {payment:payment,totalPayment:payment*months,totalInterest:totalInterest,
      totalPrincipal:totalPrincipal,balance:balance,years:years};
  }

  function render(res){
    document.getElementById('s-payment').textContent=fmt(res.payment);
    document.getElementById('s-total').textContent=fmt(res.totalPayment);
    document.getElementById('s-interest').textContent=fmt(res.totalInterest);
    var pPct=res.totalPayment>0?(res.totalPrincipal/res.totalPayment*100):0;
    var iPct=res.totalPayment>0?(res.totalInterest/res.totalPayment*100):0;
    document.getElementById('bar-principal').style.width=pPct+'%';
    document.getElementById('bar-interest').style.width=iPct+'%';
    document.getElementById('pct-principal').textContent=pct(pPct);
    document.getElementById('pct-interest').textContent=pct(iPct);

    var html='';
    for(var i=0;i<res.years.length;i++){
      var yr=res.years[i];
      html+='<tr><td>'+yr.year+'. év</td>'
        +'<td>'+fmt(yr.principal)+'</td>'
        +'<td>'+fmt(yr.interest)+'</td>'
        +'<td>'+fmt(yr.payment)+'</td>'
        +'<td class="muted">'+fmt(res.balance)+'</td></tr>';
    }
    tbody.innerHTML=html;
    summary.hidden=false; breakdown.hidden=false;
  }

  function showEmpty(msg){
    summary.hidden=true; breakdown.hidden=true; tbody.innerHTML='';
    if(msg){ errEl.textContent=msg; live.textContent=msg; }
  }

  function readInputs(){
    var amount=parseFloat(amountEl.value);
    var rate=parseFloat(rateEl.value);
    var months=parseInt(monthsEl.value,10);
    if(!isFinite(amount)||amount<=0) return {err:'Adj meg egy pozitív hitelösszeget forintban.'};
    if(!isFinite(rate)||rate<0) return {err:'Az éves kamat nem lehet negatív.'};
    if(!isFinite(months)||months<1||months!==parseFloat(monthsEl.value)) return {err:'A futamidő legyen legalább 1 egész hónap.'};
    return {amount:amount,rate:rate,months:months};
  }

  function run(save){
    var v=readInputs();
    if(v.err){ showEmpty(v.err); return; }
    errEl.textContent='';
    var res=compute(v.amount,v.rate,v.months);
    render(res);
    live.textContent='Havi törlesztőrészlet: '+fmt(res.payment);
    if(save && window.alfy && window.alfy.storage){
      window.alfy.storage.set(KEY,{amount:v.amount,rate:v.rate,months:v.months});
    }
  }

  form.addEventListener('submit',function(e){ e.preventDefault(); run(true); });

  function init(){
    var load=function(){
      var saved=null;
      try{ saved=window.alfy&&window.alfy.storage?window.alfy.storage.get(KEY):null; }catch(e){}
      var done=function(v){
        if(v&&v.amount!=null){
          amountEl.value=v.amount; rateEl.value=v.rate; monthsEl.value=v.months;
          run(false);
        } else {
          showEmpty('Még nincs számítás. Add meg a hitelösszeget, a kamatot és a futamidőt, majd nyomd meg a Számolás gombot.');
        }
      };
      if(saved&&saved.then){ saved.then(done,function(){done(null);}); } else { done(saved); }
    };
    if(window.alfy&&window.alfy.storage){ load(); } else { load(); }
  }

  init();
})();
</script>
</body>
</html>
